static void Wire(){Guard();if(SceneManager.GetActiveScene().path!=ScenePath)throw new Exception("Wrong scene");var root=GameObject.Find("HandsLab_Quest3");var origin=root.GetComponentInChildren<Unity.XR.CoreUtils.XROrigin>();var rig=origin.transform.Find("UnityXRComprehensiveInteractionRig");// Lab-owned cadence: button-only changes must propagate even when the device pose is stationary.
