var tpd=origin.Camera.GetComponent<UnityEngine.InputSystem.XR.TrackedPoseDriver>();tpd.enabled=true;tpd.positionInput=new UnityEngine.InputSystem.InputActionProperty(new UnityEngine.InputSystem.InputAction("HandsLab HMD Position",UnityEngine.InputSystem.InputActionType.Value,"<XRHMD>/centerEyePosition",expectedControlType:"Vector3"));tpd.rotationInput=new UnityEngine.InputSystem.InputActionProperty(new UnityEngine.InputSystem.InputAction("HandsLab HMD Rotation",UnityEngine.InputSystem.InputActionType.Value,"<XRHMD>/centerEyeRotation",expectedControlType:"Quaternion"));tpd.trackingStateInput=new UnityEngine.InputSystem.InputActionProperty(new UnityEngine.InputSystem.InputAction("HandsLab HMD Tracking",UnityEngine.InputSystem.InputActionType.Value,"<XRHMD>/trackingState",expectedControlType:"Integer"));var guards=root.GetComponents<HandsLabInputGuard>();if(guards.Length==0){guards=new[]{root.AddComponent<HandsLabInputGuard>(),root.AddComponent<HandsLabInputGuard>()};guards[0].ConfigureFromRig(rig,Handedness.Left);guards[1].ConfigureFromRig(rig,Handedness.Right);}foreach(var ray in panel.GetComponentsInChildren<RayInteractable>(true)){var occ=ray.GetComponent<HandsLabUIOcclusion>()??ray.gameObject.AddComponent<HandsLabUIOcclusion>();occ.Configure(ray,panel.transform);}foreach(var g in guards){g.uiClearanceColliders=panel.GetComponentsInChildren<Collider>(true);var group=g.interactionsRoot.GetComponent<BestHoverInteractorGroup>();var so=new SerializedObject(group);var prop=so.FindProperty("_interactors");var list=Enumerable.Range(0,prop.arraySize).Select(i=>prop.GetArrayElementAtIndex(i).objectReferenceValue).OfType<IInteractor>().OrderBy(i=>i is PokeInteractor?0:i is RayInteractor?1:2).ToList();group.InjectInteractors(list);}var session=root.GetComponent<HandsLabSession>()??root.AddComponent<HandsLabSession>();session.origin=origin.transform;session.trackingSpace=origin.CameraFloorOffsetObject.transform;session.head=origin.Camera;session.panel=panel;session.guards=guar